'use strict';
const W=window.WEST_GUIDE,qs=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=file=>'assets/farwest/'+file,heart='<svg aria-hidden="true"><use href="#heart"/></svg>';let toastTimer,filter='all',search='',district='kailali',route='lowlands',galleryIndex=0,galleryTimer=null;
let state={saved:[],route:null,departure:'',packing:[],notes:'',budget:{people:2,days:7,stay:'',food:'',transport:'',extras:'',buffer:15}},storageOkay=true;
try{const s=JSON.parse(localStorage.getItem('nepal-farwest-journey')||'null');if(s&&typeof s==='object'){state.saved=Array.isArray(s.saved)?s.saved.filter(id=>W.places.some(p=>p.id===id)):[];state.route=W.routes.some(r=>r.id===s.route)?s.route:null;state.departure=/^\d{4}-\d{2}-\d{2}$/.test(s.departure||'')?s.departure:'';state.packing=Array.isArray(s.packing)?s.packing.filter(x=>Number.isInteger(x)&&x>=0&&x<W.packing.length):[];state.notes=typeof s.notes==='string'?s.notes.slice(0,8000):'';if(s.budget&&typeof s.budget==='object')for(const k of Object.keys(state.budget)){const v=s.budget[k];if(v===''||Number.isFinite(Number(v)))state.budget[k]=v;}}}catch{storageOkay=false;}
function toast(t){qs('#fw-toast').textContent=t;qs('#fw-toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>qs('#fw-toast').classList.remove('show'),3000);}
function save(){try{localStorage.setItem('nepal-farwest-journey',JSON.stringify(state));const all=JSON.parse(localStorage.getItem('nepal-saved')||'[]');const national=Array.isArray(all)?all.filter(x=>typeof x==='string'&&!x.startsWith('west-')):[];localStorage.setItem('nepal-saved',JSON.stringify([...national,...state.saved.map(id=>'west-'+id)]));return true;}catch{storageOkay=false;toast('Kept for this visit. Download a travel brief to keep a copy.');return false;}}
function modal(el){qa('dialog[open]').forEach(d=>d.close());el.showModal();document.body.classList.add('modal-open');}
qa('dialog').forEach(d=>{qs('[data-close]',d).addEventListener('click',()=>d.close());d.addEventListener('close',()=>{if(!qs('dialog[open]'))document.body.classList.remove('modal-open');});d.addEventListener('click',e=>{if(e.target!==d)return;const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();});});
function photoCredit(file){return W.media.photos.find(p=>p.file===file);}
function creditHTML(file){const p=photoCredit(file);return p?`${esc(p.author)} / <a href="${p.source}" target="_blank" rel="noopener">Wikimedia Commons ↗</a> · <a href="${p.license_url}" target="_blank" rel="noopener">${esc(p.license)}</a> · Resized and recompressed.`:'';}
function renderPlaces(){const term=search.trim().toLowerCase(),items=W.places.filter(p=>(filter==='all'||filter==='saved'&&state.saved.includes(p.id)||p.group===filter)&&(!term||[p.name,p.tagline,p.description,p.category,p.group,...p.districts].join(' ').toLowerCase().includes(term)));qs('#fw-results').textContent=`${items.length} ${items.length===1?'place':'places'} / 11 ways to discover the far west`;qs('#fw-reset-filters').hidden=filter==='all'&&!search;qs('#fw-place-grid').innerHTML=items.length?items.map(p=>`<article class="fw-place"><div class="fw-place-image${p.image?'':' fw-place-type'}">${p.image?`<img src="${asset(p.image)}" alt="${esc(p.alt)}" loading="lazy">`:`<div class="fw-type-art"><span>THE SACRED HILLS</span><strong>${esc(p.name)}</strong><small>${esc(p.districts.join(' · '))}</small></div>`}<button class="fw-place-open" data-place="${p.id}" aria-label="Explore ${esc(p.name)}"><span class="fw-place-category">${p.label}</span><span class="fw-place-title"><h3>${esc(p.name)}</h3><p>${esc(p.tagline)}</p><span>↗</span></span></button><button class="fw-save" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${state.saved.includes(p.id)}">${heart}</button></div><div class="fw-place-meta"><span>${esc(p.districts.length>2?'Four districts / Khaptad':p.districts.join(' · '))}</span><span>${esc(p.effortShort)}</span></div></article>`).join(''):`<div class="fw-empty"><h3>A different search might lead somewhere.</h3><p>${filter==='saved'?'Tap a heart on a place to add it to your journey.':'Try a place, district or experience such as lakes, Doti or wildlife.'}</p><button class="button saffron" id="fw-empty-reset">Explore all places ↗</button></div>`;qs('#fw-empty-reset')?.addEventListener('click',resetFilters);}
function resetFilters(){filter='all';search='';qs('#fw-search').value='';updateFilters();renderPlaces();}
function updateFilters(){qa('[data-west-filter]').forEach(b=>{const selected=b.dataset.westFilter===filter;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected);});}
qs('#fw-search').addEventListener('input',e=>{search=e.target.value;renderPlaces();});qs('#fw-reset-filters').addEventListener('click',resetFilters);qa('[data-west-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.westFilter;updateFilters();renderPlaces();}));
function toggleSaved(id){if(!W.places.some(p=>p.id===id))return;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();updateSaved();if(filter==='saved')renderPlaces();if(qs('#fw-notebook').open)renderNotebook();toast(state.saved.includes(id)?'Added to your Far West journey.':'Removed from your saved places.');}
function updateSaved(){qs('#fw-saved-count').textContent=state.saved.length;qa('[data-save]').forEach(b=>{const p=W.places.find(x=>x.id===b.dataset.save),yes=state.saved.includes(p.id);b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',(yes?'Unsave ':'Save ')+p.name);if(!b.classList.contains('fw-save'))b.innerHTML=yes?'Saved to your journey ♡':'Save this place ♡';});}
function detail(id,push=false){const p=W.places.find(x=>x.id===id);if(!p)return;qs('#fw-detail-content').innerHTML=`<div class="fw-detail-hero${p.image?'':' fw-place-type'}">${p.image?`<img src="${asset(p.image)}" alt="${esc(p.alt)}">`:''}<div class="fw-detail-heading"><span>${esc(p.districts.join(' · ').toUpperCase())} / ${p.label}</span><h2>${esc(p.name)}</h2></div></div><div class="fw-detail-body"><div class="fw-detail-facts"><span><small>THE EXPERIENCE</small>${esc(p.effortShort)}</span><span><small>WHEN TO THINK ABOUT IT</small>${esc(p.seasonShort)}</span><span><small>YOUR PACE</small>Locally planned · flexible</span></div><div class="fw-detail-tabs" role="tablist" aria-label="Destination guide chapters"><button role="tab" id="detail-tab-overview" aria-selected="true" aria-controls="detail-pane-overview" data-detail-tab="overview">The place</button><button role="tab" id="detail-tab-access" aria-selected="false" aria-controls="detail-pane-access" tabindex="-1" data-detail-tab="access">Getting there</button><button role="tab" id="detail-tab-care" aria-selected="false" aria-controls="detail-pane-care" tabindex="-1" data-detail-tab="care">Before you go</button></div><div class="fw-detail-pane" id="detail-pane-overview" role="tabpanel" aria-labelledby="detail-tab-overview"><p>${esc(p.description)}</p><h3>${esc(p.tagline)}</h3><p>${esc(p.effort)}</p></div><div class="fw-detail-pane" id="detail-pane-access" role="tabpanel" aria-labelledby="detail-tab-access" hidden><p>${esc(p.access)}</p><h3>Give the approach its own time.</h3><p>Confirm the final road or trail, your overnight stops and your return connection. Arrange help locally before leaving a reliable gateway.</p></div><div class="fw-detail-pane" id="detail-pane-care" role="tabpanel" aria-labelledby="detail-tab-care" hidden><p>${esc(p.season)}</p><h3>Travel with care.</h3><p>${esc(p.care)}</p></div><div class="fw-detail-actions"><button class="button saffron" data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'Saved to your journey ♡':'Save this place ♡'}</button><button data-copy-place="${p.id}">Copy place link ↗</button>${p.image?`<button data-gallery-file="${p.image}">See the photograph ⤢</button>`:''}</div><div class="fw-detail-source">Research: ${p.sources.map((url,i)=>`<a href="${url}" target="_blank" rel="noopener">Official source ${i+1} ↗</a>`).join(' · ')}<small>${creditHTML(p.image)}</small></div></div>`;modal(qs('#fw-detail'));wireTabs('[data-detail-tab]','data-detail-tab',name=>{qa('[data-detail-tab]').forEach(b=>{const yes=b.dataset.detailTab===name;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});qa('.fw-detail-pane').forEach(panel=>panel.hidden=panel.id!=='detail-pane-'+name);});if(push)history.replaceState(null,'','#place='+id);}
qs('#fw-detail').addEventListener('close',()=>{if(location.hash.startsWith('#place='))history.replaceState(null,'',location.pathname+'#west-explore');});
async function copyLink(id){const url=new URL('sudurpaschim.html',location.href);url.hash='place='+id;try{await navigator.clipboard.writeText(url.href);toast('Place link copied.');}catch{const input=document.createElement('textarea');input.value=url.href;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const success=document.execCommand('copy');input.remove();toast(success?'Place link copied.':'Copy the place link from your browser address bar.');}}
function wireTabs(selector,attr,select){const tabs=qa(selector);tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(b.getAttribute(attr)));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;select(tabs[n].getAttribute(attr));tabs[n].focus();});});}
qs('#fw-district-tabs').innerHTML=W.districts.map((d,i)=>`<button role="tab" id="district-${d.id}" data-district="${d.id}" aria-selected="${i===0}" aria-controls="fw-district-panel" tabindex="${i===0?0:-1}"><small>0${i+1}</small>${d.name}</button>`).join('');
function renderDistrict(id){district=id;const d=W.districts.find(x=>x.id===id),i=W.districts.indexOf(d);qa('[data-district]').forEach(b=>{const yes=b.dataset.district===id;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});qs('#fw-district-panel').setAttribute('aria-labelledby','district-'+id);const alt=W.places.find(p=>p.image===d.image)?.alt||'Khaptad landscape, a park spanning four districts';qs('#fw-district-panel').innerHTML=`<div class="fw-district-art${d.image?'':' empty'}">${d.image?`<img src="${asset(d.image)}" alt="${esc(alt)}" loading="lazy">`:`<span>${esc(d.name)}<br>The sacred hills.</span>`}<strong>0${i+1}</strong></div><div class="fw-district-copy"><div class="eyebrow">${esc(d.landscape.toUpperCase())} / SUDURPASHCHIM</div><h3>${esc(d.name)}.</h3><p>${esc(d.description)}</p><p>${esc(d.highlights.join(' · '))}</p><div class="fw-district-links">${d.places.map(id=>{const p=W.places.find(x=>x.id===id);return`<button data-place="${id}">${esc(p.name)} ↗</button>`}).join('')}</div><a class="fw-district-source" href="https://ntb.gov.np/en/sudurpaschim-province" target="_blank" rel="noopener">Regional background · Nepal Tourism Board ↗</a></div>`;}
wireTabs('[data-district]','data-district',renderDistrict);
function dateFor(day){if(!state.departure)return'';const d=new Date(state.departure+'T12:00:00');if(Number.isNaN(d.getTime()))return'';d.setDate(d.getDate()+day-1);return d.toLocaleDateString('en-GB',{day:'numeric',month:'short'});}
function stageLabel(s){const parts=s.days.split('–').map(Number);return state.departure?dateFor(parts[0])+(parts.length>1?' – '+dateFor(parts[1]):''):'DAY '+s.days;}
function renderRoute(id){route=id;const r=W.routes.find(x=>x.id===id);qa('[data-route]').forEach(b=>{const yes=b.dataset.route===id;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});qs('#fw-route-panel').setAttribute('aria-labelledby','route-'+id);const mood={lowlands:'Wetland mornings, grassland wildlife and time beside the Mahakali. A lower-elevation introduction built around the far west’s gateway towns.',hills:'Follow the road from the plains into Dadeldhura and Doti. Leave room for sacred spaces, town walks and the people who bring them to life.',khaptad:'The approach is part of the experience. Give the hill road, the walk and the quiet of Khaptad their own time.'};qs('#fw-route-panel').innerHTML=`<div class="fw-route-intro"><h3>${esc(r.name)}.</h3><p>${mood[id]}</p><div class="fw-route-tags"><span>${r.days} DAYS IN THE FAR WEST</span><span>${id==='khaptad'?'MULTI-DAY WALKING':'TOURING OUTLINE'}</span><span>FLEXIBLE, LOCALLY CONFIRMED</span></div><p>${esc(r.note)}</p></div><ol class="fw-route-timeline">${r.stages.map(s=>`<li><span>${esc(stageLabel(s))}</span><div><h4>${esc(s.place)}</h4><p>${esc(s.idea)}</p></div></li>`).join('')}</ol>`;qs('#fw-save-route').textContent=state.route===id?'Saved to your journey ♡':'Save this route ♡';}
wireTabs('[data-route]','data-route',renderRoute);qs('#fw-departure').value=state.departure;qs('#fw-departure').addEventListener('change',e=>{state.departure=e.target.value;save();renderRoute(route);});qs('#fw-save-route').addEventListener('click',()=>{state.route=route;save();renderRoute(route);toast('Route saved in your Far West journey.');});
const gallery=W.media.photos.filter(p=>p.file!=='khaptad-mist.jpg');
const photoTitles={'khaptad.jpg':['Khaptad','Where the meadows meet the sky.'],'api-himal.jpg':['Api Himal','Beyond the familiar horizon.'],'ramaroshan.jpg':['Ramaroshan','A little more room to breathe.'],'shuklaphanta.jpg':['Shuklaphanta','Give the wild its own space.'],'ghodaghodi.jpg':['Ghodaghodi Lake','Listen to the lowlands.'],'dodhara-chandani.jpg':['Dodhara–Chandani','Follow the river’s long line.'],'badimalika.jpg':['On the Badimalika trek','A rocky mountain view along the journey.'],'saipal.jpg':['Saipal, from Khaptad','A distant Himalayan horizon.'],'amargadhi.jpg':['Amargadhi Fort','History within the walls.'],'shaileshwari.jpg':['Shaileshwari, Doti','An active sacred place in Silgadhi.'],'tripurasundari.jpg':['Tripura Sundari, Baitadi','The sacred stories of the hills.'],'khaptad-mist.jpg':['Khaptad in the mist','A quieter kind of wonder.']};
function galleryTitle(p){return photoTitles[p.file]||[p.title,'A place with its own story.'];}
qs('#fw-gallery-strip').innerHTML=['api-himal.jpg','ramaroshan.jpg','shuklaphanta.jpg','dodhara-chandani.jpg','badimalika.jpg'].map(file=>{const p=gallery.find(p=>p.file===file);return`<button class="fw-gallery-thumb" data-gallery-file="${file}" aria-label="View ${esc(galleryTitle(p)[0])} photograph"><img src="${asset(file)}" alt="${esc(galleryTitle(p)[0])}" loading="lazy"><span>${esc(galleryTitle(p)[0])} ↗</span></button>`}).join('');
function renderGallery(){const p=gallery[galleryIndex],titles=galleryTitle(p);qs('#fw-gallery-image').src=asset(p.file);qs('#fw-gallery-image').alt=titles[0]+'. '+titles[1];qs('#fw-gallery-kicker').textContent='THE FAR WEST / REAL PHOTOGRAPHY';qs('#fw-gallery-title').textContent=titles[0];qs('#fw-gallery-description').textContent=titles[1];qs('#fw-gallery-credit').innerHTML=creditHTML(p.file);qs('#fw-gallery-count').textContent=String(galleryIndex+1).padStart(2,'0')+' / '+String(gallery.length).padStart(2,'0');}
function stopGallery(){clearInterval(galleryTimer);galleryTimer=null;qs('#fw-gallery-play').textContent='▶';qs('#fw-gallery-play').setAttribute('aria-label','Start photographic slideshow');}
function openGallery(file){stopGallery();galleryIndex=Math.max(0,gallery.findIndex(p=>p.file===file));renderGallery();modal(qs('#fw-gallery'));}
function stepGallery(n){galleryIndex=(galleryIndex+n+gallery.length)%gallery.length;renderGallery();}
qs('#fw-open-gallery').addEventListener('click',()=>openGallery('khaptad.jpg'));qs('#fw-gallery-prev').addEventListener('click',()=>{stopGallery();stepGallery(-1);});qs('#fw-gallery-next').addEventListener('click',()=>{stopGallery();stepGallery(1);});qs('#fw-gallery-play').addEventListener('click',()=>{if(galleryTimer){stopGallery();return;}galleryTimer=setInterval(()=>stepGallery(1),6500);qs('#fw-gallery-play').textContent='Ⅱ';qs('#fw-gallery-play').setAttribute('aria-label','Pause photographic slideshow');});qs('#fw-gallery').addEventListener('close',stopGallery);qs('#fw-gallery').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();stopGallery();stepGallery(e.key==='ArrowLeft'?-1:1);}});
const film=W.media.videos[0];qa('[data-west-film]').forEach(b=>b.addEventListener('click',()=>{const v=qs('#fw-video');v.src=asset(film.file);qs('#fw-video-credit').innerHTML=`A 28-second excerpt of real ground-level footage from Khaptad, identified by the creator. Silent. Film by <a href="${film.source}" target="_blank" rel="noopener">${esc(film.author)} / Pexels ↗</a> · <a href="${film.license_url}" target="_blank" rel="noopener">${film.license}</a>.`;modal(qs('#fw-video-dialog'));v.load();v.play().catch(()=>{});}));qs('#fw-video-dialog').addEventListener('close',()=>{qs('#fw-video').pause();qs('#fw-video').removeAttribute('src');qs('#fw-video').load();});
qs('#fw-culture-copy').innerHTML=W.culture.map(c=>`<article><h3>${esc(c.title)}.</h3><p>${esc(c.text)}</p></article>`).join('');qs('#fw-guide-grid').innerHTML=W.fieldGuide.map(q=>`<details><summary>${esc(q.question)}</summary><p>${esc(q.answer)}</p>${q.source?`<a href="${q.source}" target="_blank" rel="noopener">Official guidance ↗</a>`:''}</details>`).join('');
function number(id,min=0,max=1e8){const n=Number(qs('#budget-'+id).value);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):min;}
function budgetCalc(){const people=Math.round(number('people',1,30)),days=Math.round(number('days',1,90)),stay=number('stay')*people*days,food=number('food')*people*days,transport=number('transport'),extras=number('extras'),base=stay+food+transport+extras,buffer=base*number('buffer',0,40)/100;return{people,days,stay,food,transport,extras,base,buffer,total:base+buffer,perPerson:(base+buffer)/people};}
const money=n=>'NPR '+Math.round(n).toLocaleString('en-US');
function renderBudget(persist=false){const b=budgetCalc();qs('#budget-buffer-label').textContent=number('buffer',0,40)+'%';qs('#budget-total').textContent=money(b.total);qs('#budget-per-person').textContent=b.total?money(b.perPerson)+' per person · '+b.people+' travelers · '+b.days+' days':'Add your own estimates to begin.';qs('#budget-breakdown').innerHTML=b.total?[['Stays',b.stay],['Food',b.food],['Transport',b.transport],['Guides, permits & extras',b.extras],['Contingency',b.buffer]].map(([k,v])=>`<div><span>${k}</span><span>${money(v)}</span></div>`).join(''):'';if(persist){for(const k of Object.keys(state.budget))state.budget[k]=qs('#budget-'+k).value;save();}}
for(const [k,v]of Object.entries(state.budget)){qs('#budget-'+k).value=v;qs('#budget-'+k).addEventListener('input',()=>renderBudget(true));}
function renderPacking(){qs('#packing-list').innerHTML=W.packing.map((p,i)=>`<label><input type="checkbox" data-pack="${i}" ${state.packing.includes(i)?'checked':''}><span>${esc(p)}</span></label>`).join('');qs('#packing-progress').textContent=state.packing.length+' of '+W.packing.length+' essentials checked';qs('#packing-meter').max=W.packing.length;qs('#packing-meter').value=state.packing.length;}
qs('#packing-list').addEventListener('change',e=>{const i=+e.target.dataset.pack;if(!Number.isInteger(i))return;state.packing=e.target.checked?[...new Set([...state.packing,i])]:state.packing.filter(x=>x!==i);save();qs('#packing-progress').textContent=state.packing.length+' of '+W.packing.length+' essentials checked';qs('#packing-meter').value=state.packing.length;});qs('#packing-reset').addEventListener('click',()=>{state.packing=[];save();renderPacking();});qs('#fw-notes').value=state.notes;qs('#fw-notes').addEventListener('input',e=>{state.notes=e.target.value;const okay=save();qs('#notes-status').textContent=okay?'Saved in this browser · '+state.notes.length+' / 8000 characters':'Kept for this visit. Download a brief to keep a copy.';});
function setTool(name){qa('[data-tool]').forEach(b=>{const yes=b.dataset.tool===name;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});qa('.fw-tool-panel').forEach(p=>p.hidden=p.id!=='fw-tool-'+name);}
wireTabs('[data-tool]','data-tool',setTool);
function renderNotebook(){const r=W.routes.find(r=>r.id===state.route);qs('#fw-notebook-content').innerHTML=(state.saved.length?state.saved.map(id=>{const p=W.places.find(p=>p.id===id);return`<div class="fw-notebook-place">${p.image?`<img src="${asset(p.image)}" alt="${esc(p.alt)}">`:''}<button data-place="${id}"><strong>${esc(p.name)}</strong><small>${esc(p.districts.join(' · '))}</small></button><button data-save="${id}" aria-label="Remove ${esc(p.name)} from saved places">Remove</button></div>`}).join(''):'<div class="fw-notebook-empty">Tap a heart on any place to collect the ones that call to you.</div>')+`<div class="fw-notebook-route"><h3>${r?esc(r.name):'Your route is still an open road.'}</h3><p>${r?r.days+' days in the far west'+(state.departure?' · Starting '+esc(state.departure):''):'Explore three route ideas and save one to start shaping your journey.'}</p><button class="text-link" id="fw-notebook-route-open">${r?'Open saved route':'Explore route ideas'} ↗</button></div>`;qs('#fw-notebook-route-open').addEventListener('click',()=>{qs('#fw-notebook').close();if(state.route)renderRoute(state.route);qs('#west-routes').scrollIntoView({behavior:reduced.matches?'instant':'smooth'});});}
qa('[data-notebook]').forEach(b=>b.addEventListener('click',()=>{renderNotebook();modal(qs('#fw-notebook'));}));
function exportBrief(){const r=W.routes.find(r=>r.id===(state.route||route)),b=budgetCalc();const text=['NEPAL — BEYOND THE ORDINARY','MY SUDURPASHCHIM TRAVEL BRIEF','Research checked 22 October 2026. Editorial planning, not confirmed arrangements.','', 'MY PLACES',...(state.saved.length?state.saved.map(id=>{const p=W.places.find(p=>p.id===id);return p.name+' | '+p.districts.join(', ')+'\n'+p.description+'\nApproach: '+p.access+'\nBefore you go: '+p.season+' '+p.care+'\nSource: '+p.sources.join(' | ')+'\n';}):['No places saved yet.']), '',r.name.toUpperCase()+' | '+r.days+' DAYS',state.departure?'Starting '+state.departure:'Dates to be decided',...r.stages.map(s=>stageLabel(s)+' | '+s.place+'\n'+s.idea),r.note,'','MY OWN BUDGET ESTIMATES (NOT LIVE PRICES)',b.people+' people / '+b.days+' days','Stays: '+money(b.stay),'Food: '+money(b.food),'Transport: '+money(b.transport),'Guides, permits and extras: '+money(b.extras),'Contingency: '+money(b.buffer),'Total: '+money(b.total),'Per person: '+money(b.perPerson),'','PACKING',...W.packing.map((x,i)=>(state.packing.includes(i)?'[x] ':'[ ] ')+x),'','MY NOTES',state.notes||'No notes yet.','','BEFORE YOU GO','Confirm roads, weather, permits, guides, stays, support and actual transport for your dates. This guide is not a high-altitude trek schedule or a booking. Travel outside the far west needs additional time.','','https://nepal-beyond-ordinary.brinybull4.chatgpt.site/sudurpaschim.html'].join('\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='My-Sudurpashchim-Travel-Brief.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Your travel brief is ready to download.');}
qa('[data-export]').forEach(b=>b.addEventListener('click',exportBrief));
function showSources(){qs('#fw-source-content').innerHTML=`<h3>Travel research</h3><p>Checked 22 October 2026. Official source material supports the destination guides. Routes, packing and budget tools are editorial planning aids. Sources can be undated; prices, access and availability are not verified live.</p><ul>${W.sourceRegister.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></li>`).join('')}</ul><h3>Real photography</h3><p>Photos are resized and JPEG recompressed. Each image retains its listed Creative Commons license; the bridge photo uses CC BY 3.0 and the others use CC BY-SA 4.0. Display crops do not change the underlying photo files. Some photographs are older and do not show current conditions.</p>${W.media.photos.map(p=>`<div class="fw-source-item"><strong>${esc(galleryTitle(p)[0])}</strong><p>${creditHTML(p.file)}</p></div>`).join('')}<h3>Khaptad film</h3><p><a href="${film.source}" target="_blank" rel="noopener">${esc(film.author)} / Pexels ↗</a> · <a href="${film.license_url}" target="_blank" rel="noopener">Pexels License</a>. ${esc(film.changes)} Ground-level footage; not a drone or 360° film.</p><h3>Living culture</h3><ul>${W.culture.filter(c=>c.source).map(c=>`<li><a href="${c.source}" target="_blank" rel="noopener">${esc(c.title)} · Nepal Tourism Board ↗</a></li>`).join('')}</ul><p>This is an independent travel guide. No bookings, payments or live accommodation availability are offered. Your saved places, notes and estimates stay in your browser.</p>`;modal(qs('#fw-sources'));}
qs('#fw-open-sources').addEventListener('click',showSources);qs('#fw-footer-credits').addEventListener('click',showSources);
document.addEventListener('click',e=>{const b=e.target.closest('[data-place],[data-save],[data-copy-place],[data-gallery-file]');if(!b)return;if(b.dataset.place)detail(b.dataset.place,true);else if(b.dataset.save)toggleSaved(b.dataset.save);else if(b.dataset.copyPlace)copyLink(b.dataset.copyPlace);else if(b.dataset.galleryFile)openGallery(b.dataset.galleryFile);});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motion=!reduced.matches;
function setMotion(){document.body.classList.toggle('fw-no-motion',!motion);qs('#fw-motion').textContent=motion?'Ⅱ PAUSE MOTION':'▶ PLAY MOTION';qs('#fw-motion').setAttribute('aria-pressed',motion);}
qs('#fw-motion').addEventListener('click',()=>{motion=!motion;setMotion();});reduced.addEventListener('change',()=>{motion=!reduced.matches;setMotion();if(reduced.matches)stopGallery();});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopGallery();qs('#fw-video').pause();}});
const chapterObserver=new IntersectionObserver(entries=>{entries.filter(e=>e.isIntersecting).forEach(e=>{qa('.fw-chapters a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));});},{rootMargin:'-15% 0px -65% 0px'});qa('main>section[id]').forEach(s=>chapterObserver.observe(s));
renderPlaces();updateSaved();renderDistrict(district);renderRoute(state.route||route);renderBudget();renderPacking();setMotion();if(location.hash.startsWith('#place=')){detail(decodeURIComponent(location.hash.slice(7)));}addEventListener('hashchange',()=>{if(location.hash.startsWith('#place='))detail(decodeURIComponent(location.hash.slice(7)));});

if(location.hash==='#sources')showSources();
